<#
.Synopsis
Approves or rejects an existing private endpoint connection.
Approval requires the parent Cluster to contain at least one Pool.
An approval attempt when the Cluster has no Pools fails with 409 Conflict and the stable error code PrivateEndpointRequiresPool.
Rejection remains allowed when the Cluster has no Pools so that existing connections can be cleaned up.
.Description
Approves or rejects an existing private endpoint connection.
Approval requires the parent Cluster to contain at least one Pool.
An approval attempt when the Cluster has no Pools fails with 409 Conflict and the stable error code PrivateEndpointRequiresPool.
Rejection remains allowed when the Cluster has no Pools so that existing connections can be cleaned up.
.Example
Invoke-AzHorizonDbRejectPrivateEndpointConnection -ResourceGroupName 'example-resource-group' -ClusterName 'example-cluster' -PrivateEndpointConnectionName 'example-private-endpoint-connection' -PrivateLinkServiceConnectionStateStatus 'Approved' -PrivateLinkServiceConnectionStateDescription 'Approved for the production database network' | Format-List -Property Name, PrivateLinkServiceConnectionStateStatus, PrivateLinkServiceConnectionStateDescription, ProvisioningState
.Example
Invoke-AzHorizonDbRejectPrivateEndpointConnection -ResourceGroupName 'example-resource-group' -ClusterName 'example-cluster' -PrivateEndpointConnectionName 'example-private-endpoint-connection' -PrivateLinkServiceConnectionStateStatus 'Rejected' -PrivateLinkServiceConnectionStateDescription 'Connection is not authorized'

.Inputs
Microsoft.Azure.PowerShell.Cmdlets.HorizonDB.Models.IHorizonDbIdentity
.Inputs
Microsoft.Azure.PowerShell.Cmdlets.HorizonDB.Models.IPrivateEndpointConnection
.Outputs
Microsoft.Azure.PowerShell.Cmdlets.HorizonDB.Models.IPrivateEndpointConnection
.Notes
COMPLEX PARAMETER PROPERTIES

To create the parameters described below, construct a hash table containing the appropriate properties. For information on hash tables, run Get-Help about_Hash_Tables.

CLUSTERINPUTOBJECT <IHorizonDbIdentity>: Identity Parameter
  [AssignmentName <String>]: The caller-selected name of the identity assignment.
  [ClusterName <String>]: The name of the HorizonDB cluster.
  [ConfigurationName <String>]: The caller-selected ARM-safe name of the change data capture configuration. The exact PostgreSQL database name is stored in properties.databaseName.
  [DestinationName <String>]: The caller-selected name of the change data capture destination.
  [EndpointName <String>]: The platform-assigned name of the HorizonDB endpoint. A Cluster-scoped ReadWrite Endpoint has exactly the same name as its associated Cluster. A Pool-scoped Endpoint has exactly the same name as its associated Pool.
  [FirewallRuleName <String>]: The name of the HorizonDB pool firewall rule. The name must be 1 through 80 characters, contain only ASCII letters, digits, underscores, periods, and hyphens, start with a letter or digit, and end with a letter, digit, or underscore.
  [GroupName <String>]: The name of the private link resource.
  [Id <String>]: Resource identity path
  [Location <String>]: The name of the Azure region.
  [LogCaptureConfigurationName <String>]: The name of the LogCaptureConfiguration
  [LogFileName <String>]: The name of the LogFile
  [MaintenanceEventId <String>]: The identifier of the maintenance event.
  [Name <String>]: The name of the DefaultParameterGroup
  [NodeName <String>]: The name of the Node
  [ObjectId <String>]: The Microsoft Entra object identifier of the principal mapped to the PostgreSQL role, represented as an RFC 4122 GUID.
  [ParameterGroupName <String>]: The name of the HorizonDB parameter group.
  [PoolName <String>]: The name of the HorizonDB pool.
  [PrivateEndpointConnectionName <String>]: The name of the private endpoint connection associated with the Azure resource.
  [ResourceGroupName <String>]: The name of the resource group. The name is case insensitive.
  [SubscriptionId <String>]: The ID of the target subscription. The value must be an UUID.

INPUTOBJECT <IHorizonDbIdentity>: Identity Parameter
  [AssignmentName <String>]: The caller-selected name of the identity assignment.
  [ClusterName <String>]: The name of the HorizonDB cluster.
