  [ClusterName <String>]: The name of the HorizonDB cluster.
  [ConfigurationName <String>]: The caller-selected ARM-safe name of the change data capture configuration. The exact PostgreSQL database name is stored in properties.databaseName.
  [DestinationName <String>]: The caller-selected name of the change data capture destination.
  [EndpointName <String>]: The platform-assigned name of the HorizonDB endpoint. A Cluster-scoped ReadWrite Endpoint has exactly the same name as its associated Cluster. A Pool-scoped Endpoint has exactly the same name as its associated Pool.
  [FirewallRuleName <String>]: The name of the HorizonDB pool firewall rule. The name must be 1 through 80 characters, contain only ASCII letters, digits, underscores, periods, and hyphens, start with a letter or digit, and end with a letter, digit, or underscore.
  [GroupName <String>]: The name of the private link resource.
