<#
.Synopsis
Deletes a change data capture configuration after destination-side replication has been stopped or detached.
This operation never deletes the Microsoft Fabric mirrored-database item.
.Description
Deletes a change data capture configuration after destination-side replication has been stopped or detached.
This operation never deletes the Microsoft Fabric mirrored-database item.
.Example
