  [FirewallRuleName <String>]: The name of the HorizonDB pool firewall rule. The name must be 1 through 80 characters, contain only ASCII letters, digits, underscores, periods, and hyphens, start with a letter or digit, and end with a letter, digit, or underscore.
  [GroupName <String>]: The name of the private link resource.
  [Id <String>]: Resource identity path
  [Location <String>]: The name of the Azure region.
  [LogCaptureConfigurationName <String>]: The name of the LogCaptureConfiguration
  [LogFileName <String>]: The name of the LogFile
  [MaintenanceEventId <String>]: The identifier of the maintenance event.
  [Name <String>]: The name of the DefaultParameterGroup
