.Synopsis
Update an existing HorizonDB pool, including its node allocation, selected compute model properties, compute model type, high-availability configuration, or associated parameter group.
Omitted nodeCount and highAvailability.mode values preserve their existing values; the service recursively merges the PATCH before atomically validating the effective tuple.
nodeCount, when supplied, must be 1 through 16.
Disabled is valid only when the effective nodeCount is 1.
AnyZone and ZoneRedundant are valid only when the effective nodeCount is 2 through 16.
Therefore, crossing between those node-count ranges requires nodeCount and highAvailability.mode to be changed together.
AnyZone permits same-zone or cross-zone placement.
Changing from AnyZone to ZoneRedundant may allocate a replacement node in another availability zone and replace a read-only node, disconnecting connections to the replaced node.
If all requested nodes or the required zonal topology cannot be provisioned, the long-running operation fails and the previous resource state is preserved.
To deallocate runtime compute without changing the configured nodeCount, use the Pool stop action.
When parameterGroup is supplied, both parameterGroupResourceId and applyMethod are required.
The pool can switch its association in either direction between the corresponding default parameter group and a customer-created parameter group.
applyMethod controls when dynamic parameter changes become effective.
Static parameter changes always require a customer-initiated Restart; Stop followed by Start and scheduled maintenance do not apply pending changes.
Subtype-specific compute constraints are validated against the recursively merged configuration.
.Description
Update an existing HorizonDB pool, including its node allocation, selected compute model properties, compute model type, high-availability configuration, or associated parameter group.
Omitted nodeCount and highAvailability.mode values preserve their existing values; the service recursively merges the PATCH before atomically validating the effective tuple.
nodeCount, when supplied, must be 1 through 16.
Disabled is valid only when the effective nodeCount is 1.
AnyZone and ZoneRedundant are valid only when the effective nodeCount is 2 through 16.
Therefore, crossing between those node-count ranges requires nodeCount and highAvailability.mode to be changed together.
AnyZone permits same-zone or cross-zone placement.
Changing from AnyZone to ZoneRedundant may allocate a replacement node in another availability zone and replace a read-only node, disconnecting connections to the replaced node.
If all requested nodes or the required zonal topology cannot be provisioned, the long-running operation fails and the previous resource state is preserved.
To deallocate runtime compute without changing the configured nodeCount, use the Pool stop action.
When parameterGroup is supplied, both parameterGroupResourceId and applyMethod are required.
The pool can switch its association in either direction between the corresponding default parameter group and a customer-created parameter group.
applyMethod controls when dynamic parameter changes become effective.
Static parameter changes always require a customer-initiated Restart; Stop followed by Start and scheduled maintenance do not apply pending changes.
Subtype-specific compute constraints are validated against the recursively merged configuration.
.Example
Update-AzHorizonDbPool -ResourceGroupName 'example-resource-group' -ClusterName 'example-cluster' -Name 'example-pool-01' -ComputeModelVCore 16 -ScheduledMaintenanceManagementType 'System' | Format-List -Property Name, ComputeModelVCore, NodeCount, HighAvailabilityMode, State, ProvisioningState, ParameterGroupApplyMethod, ParameterGroupSyncStatus
.Example
Update-AzHorizonDbPool -ResourceGroupName 'example-resource-group' -ClusterName 'example-cluster' -Name 'example-pool-01' -HighAvailabilityMode 'ZoneRedundant' | Format-List -Property Name, ComputeModelVCore, NodeCount, HighAvailabilityMode, State, ProvisioningState, ParameterGroupApplyMethod, ParameterGroupSyncStatus
.Example
$subscriptionId = (Get-AzContext).Subscription.Id
$parameterGroupId = "/subscriptions/$subscriptionId/resourceGroups/example-resource-group/providers/Microsoft.HorizonDb/parameterGroups/production-parameters"

Update-AzHorizonDbPool -ResourceGroupName 'example-resource-group' -ClusterName 'example-cluster' -Name 'example-pool-01' -ParameterGroupResourceId $parameterGroupId -ParameterGroupApplyMethod 'Immediate' | Format-List -Property Name, ComputeModelVCore, NodeCount, HighAvailabilityMode, State, ProvisioningState, ParameterGroupApplyMethod, ParameterGroupSyncStatus, ParameterGroupResourceId
.Example
$subscriptionId = (Get-AzContext).Subscription.Id
$parameterGroupId = "/subscriptions/$subscriptionId/resourceGroups/example-resource-group/providers/Microsoft.HorizonDb/parameterGroups/maintenance-window-parameters"

Update-AzHorizonDbPool -ResourceGroupName 'example-resource-group' -ClusterName 'example-cluster' -Name 'example-pool-01' -ParameterGroupResourceId $parameterGroupId -ParameterGroupApplyMethod 'PendingReboot' | Format-List -Property Name, ComputeModelVCore, NodeCount, HighAvailabilityMode, State, ProvisioningState, ParameterGroupApplyMethod, ParameterGroupSyncStatus, ParameterGroupResourceId
.Example
$subscriptionId = (Get-AzContext).Subscription.Id
$parameterGroupId = "/subscriptions/$subscriptionId/providers/Microsoft.HorizonDb/locations/eastus2/parameterGroups/default-postgresql-17-provisioned"

Update-AzHorizonDbPool -ResourceGroupName 'example-resource-group' -ClusterName 'example-cluster' -Name 'example-pool-01' -ParameterGroupResourceId $parameterGroupId -ParameterGroupApplyMethod 'Immediate' | Format-List -Property Name, ComputeModelVCore, NodeCount, HighAvailabilityMode, State, ProvisioningState, ParameterGroupApplyMethod, ParameterGroupSyncStatus, ParameterGroupResourceId

.Inputs
Microsoft.Azure.PowerShell.Cmdlets.HorizonDB.Models.IHorizonDbIdentity
.Outputs
Microsoft.Azure.PowerShell.Cmdlets.HorizonDB.Models.IPool
.Notes
COMPLEX PARAMETER PROPERTIES

To create the parameters described below, construct a hash table containing the appropriate properties. For information on hash tables, run Get-Help about_Hash_Tables.

CLUSTERINPUTOBJECT <IHorizonDbIdentity>: Identity Parameter
  [AssignmentName <String>]: The caller-selected name of the identity assignment.
  [ClusterName <String>]: The name of the HorizonDB cluster.
  [ConfigurationName <String>]: The caller-selected ARM-safe name of the change data capture configuration. The exact PostgreSQL database name is stored in properties.databaseName.
  [DestinationName <String>]: The caller-selected name of the change data capture destination.
  [EndpointName <String>]: The platform-assigned name of the HorizonDB endpoint. A Cluster-scoped ReadWrite Endpoint has exactly the same name as its associated Cluster. A Pool-scoped Endpoint has exactly the same name as its associated Pool.
  [FirewallRuleName <String>]: The name of the HorizonDB pool firewall rule. The name must be 1 through 80 characters, contain only ASCII letters, digits, underscores, periods, and hyphens, start with a letter or digit, and end with a letter, digit, or underscore.
  [GroupName <String>]: The name of the private link resource.
  [Id <String>]: Resource identity path
  [Location <String>]: The name of the Azure region.
  [LogCaptureConfigurationName <String>]: The name of the LogCaptureConfiguration
  [LogFileName <String>]: The name of the LogFile
  [MaintenanceEventId <String>]: The identifier of the maintenance event.
  [Name <String>]: The name of the DefaultParameterGroup
  [NodeName <String>]: The name of the Node
  [ObjectId <String>]: The Microsoft Entra object identifier of the principal mapped to the PostgreSQL role, represented as an RFC 4122 GUID.
  [ParameterGroupName <String>]: The name of the HorizonDB parameter group.
  [PoolName <String>]: The name of the HorizonDB pool.
  [PrivateEndpointConnectionName <String>]: The name of the private endpoint connection associated with the Azure resource.
  [ResourceGroupName <String>]: The name of the resource group. The name is case insensitive.
  [SubscriptionId <String>]: The ID of the target subscription. The value must be an UUID.

